class Solution {
    public int minNumber(int[] nums1, int[] nums2) {
        boolean[] in1 = new boolean[10], in2 = new boolean[10];
        for (int x : nums1) in1[x] = true;
        for (int x : nums2) in2[x] = true;
        for (int d = 1; d <= 9; d++) if (in1[d] && in2[d]) return d;
        int a = Integer.MAX_VALUE, b = Integer.MAX_VALUE;
        for (int x : nums1) a = Math.min(a, x);
        for (int x : nums2) b = Math.min(b, x);
        return 10 * Math.min(a, b) + Math.max(a, b);
    }
}

