var minNumber = function(nums1, nums2) {
    const s2 = new Set(nums2);
    let commonMin = 10;
    for (const x of nums1) if (s2.has(x)) commonMin = Math.min(commonMin, x);
    if (commonMin < 10) return commonMin;
    const a = Math.min(...nums1), b = Math.min(...nums2);
    return 10 * Math.min(a, b) + Math.max(a, b);
};
